sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        //This BR will parse the payload field from widget inbound table and populate the client trader name field on trade case when event status is CLIENT_TRADER_NAME_PROVIDED
        var widgetPayload = current.payload;
        var result = new global.JSON.parse(widgetPayload.toString());
        var clientName = result.CLIENT_TRADERS_NAME;
        var employeeRefName = result.EMPLOYEE_REFERENCE_NAME;
        var employeeCode = result.EMPLOYEE_REFERENCE_CODE;
        var taskNum = '';
        if (typeof(result['DETAILS']) !== "undefined") {
            for (var i = 0; i < result.DETAILS.length; i++) {
                var trade = new GlideRecord('x_hsb11_hsbc_mss_t_hsbc_trade');
                trade.addQuery('u_ctac_trade_audit_0_order_id_s', result.DETAILS[i].ORDER_ID);
                trade.query();
                if (trade.next()) {
                    var tradeCase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
                    tradeCase.addQuery('financial_object', trade.getValue('sys_id'));
                    tradeCase.query();
                    if (tradeCase.next()) {
                        tradeCase.front_office_trader_s_name = employeeRefName;
                        tradeCase.front_office_trade_s_employee_code = employeeCode;
                        tradeCase.update();
                    }
                }
            }
        } else {
            var tradeTask = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
            tradeTask.addQuery("number", current.object_id);
            tradeTask.query();
            if (tradeTask.next()) {
                taskNum = tradeTask.parent;
            }

            var tradeCase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
            tradeCase.addQuery("sys_id", taskNum);
            tradeCase.query();
            if (tradeCase.next()) {
                //Update client name when event status is client trader name provided or Receive Trader Name from FO
                if (current.event_status == 'CLIENT_TRADER_NAME_PROVIDED' || current.event_status == 'Receive Trader Name from FO')
                    tradeCase.client_traders_name = clientName;

                //Update front office comments when event status is MODS to Rebook (MSSRBXCE-307)
                if (current.event_status == 'MODS to Rebook')
                    tradeCase.front_office_comments = result.MODS_TO_REBOOK_WITH_BELOW_DETAILS;

                //Update front office comments when event status is MODS to Cancel (MSSRBXCE-307)
                if (current.event_status == 'MODS to Cancel')
                    tradeCase.front_office_comments = result.MODS_TO_CANCEL_WITH_BELOW_REASON;

                //Updating the FO employee name and employee code who actioned on the trade case. 
                tradeCase.front_office_trader_s_name = employeeRefName;
                tradeCase.front_office_trade_s_employee_code = employeeCode;
                tradeCase.update();
            }
        }

    } catch (e) {
        current.status = "Error";
        current.update();
        gs.error("[BR][HSBC-Populate Trader, Emp Name on TC]: " + e.getMessage());
    }

})(current, previous);
